package com.oms.inventory.service.impl;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.inventory.service.impl.StockProcessService.*;

/** Source-scoped holds. Lock order: sorted SKU mutexes, care document, warehouses, batches. */
@Service public class StockCareService {
 @Resource JdbcTemplate jdbc;
 @Resource InventoryMutationService mutations;
 private void need(boolean b,String m){if(!b)throw new IllegalArgumentException(m);}
 private Map<String,Object> one(String sql,Object... a){List<Map<String,Object>> r=jdbc.queryForList(sql,a);need(r.size()==1,"库存来源不存在或不属于当前公司");return r.get(0);}
 public String hash(Object value){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(encode(value).getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte v:bytes)b.append(String.format("%02x",v));return b.toString();}catch(Exception e){throw new IllegalArgumentException("库存请求无法编码",e);}}
 private void identity(String c,String sn){need(c!=null&&c.matches("[A-Z0-9_-]{1,64}")&&sn.matches("(CGT|ZJ)[A-Za-z0-9_-]{1,60}"),"库存来源单号或公司无效");}
 private void lockSkus(String c,List<Map<String,Object>> lines){TreeSet<String> skus=new TreeSet<>();for(Map<String,Object> l:lines)skus.add(s(l,"sku_sn"));for(String sku:skus)one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=? FOR UPDATE",c,sku);}
 public Map<String,Object> report(String c,String sn){identity(c,sn);List<Map<String,Object>> found=jdbc.queryForList("SELECT * FROM oms_stock_care WHERE company_code=? AND document_sn=?",c,sn);if(found.isEmpty())return map("exists",false);Map<String,Object> d=found.get(0);d.put("exists",true);d.put("lines",jdbc.queryForList("SELECT h.*,b.batch_code,b.transaction_price,b.zp_available_number,b.cp_available_number FROM oms_stock_care_line h JOIN wms_inventory_batch b ON b.company_code=h.company_code AND b.id=h.batch_id WHERE h.company_code=? AND h.document_sn=? ORDER BY h.line_key",c,sn));return d;}
 public List<Map<String,Object>> balances(String c,List<Map<String,Object>> keys){need(keys!=null&&keys.size()<=200,"每批最多查询200个库存来源");if(keys.isEmpty())return Collections.emptyList();List<String> clauses=new ArrayList<>();List<Object> args=new ArrayList<>();for(Map<String,Object> k:keys){clauses.add("SELECT ? sku,? store,? batch");args.add(k.get("sku_sn"));args.add(k.get("store_code"));args.add(k.get("batch_code"));}args.add(c);return jdbc.queryForList("SELECT b.id,b.sku_sn,b.store_code,b.batch_code,b.zp_actual_number,b.cp_actual_number,b.zp_available_number,b.cp_available_number,b.zp_lock_number,b.cp_lock_number,b.version FROM ("+String.join(" UNION ALL ",clauses)+") k JOIN wms_inventory_batch b ON b.sku_sn=k.sku AND b.store_code=k.store AND b.batch_code=k.batch WHERE b.company_code=?",args.toArray());}
 private Map<String,Object> batch(String c,long id){return one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=? FOR UPDATE",c,id);}
 private void consistent(String c,String sku,String store){Map<String,Object> w=one("SELECT * FROM wms_inventory WHERE company_code=? AND sku_sn=? AND store_code=? FOR UPDATE",c,sku,store);Map<String,Object> total=one("SELECT COALESCE(SUM(zp_actual_number),0) za,COALESCE(SUM(zp_available_number),0) zv,COALESCE(SUM(zp_lock_number),0) zl,COALESCE(SUM(cp_actual_number),0) ca,COALESCE(SUM(cp_available_number),0) cv,COALESCE(SUM(cp_lock_number),0) cl FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=?",c,sku,store);for(String p:Arrays.asList("z","c")){String prefix=p.equals("z")?"zp":"cp";need(n(w,prefix+"_actual_number")==n(total,p+"a")&&n(w,prefix+"_available_number")==n(total,p+"v")&&n(w,prefix+"_lock_number")==n(total,p+"l")&&n(total,p+"a")==n(total,p+"v")+n(total,p+"l"),"仓库与批次库存不一致，请先核对");}}
 private void change(String c,Map<String,Object> b,String type,long actual,long free,long locked){String p="ZP".equals(type)?"zp":"cp";need(n(b,p+"_actual_number")+actual>=0&&n(b,p+"_available_number")+free>=0&&n(b,p+"_lock_number")+locked>=0,"原批次可用或来源锁定库存不足");for(String table:Arrays.asList("wms_inventory","wms_inventory_batch")){String where=table.endsWith("_batch")?"id=?":"sku_sn=? AND store_code=?";List<Object> args=new ArrayList<>(Arrays.asList(actual,free,locked,c));if(table.endsWith("_batch"))args.add(b.get("id"));else{args.add(b.get("sku_sn"));args.add(b.get("store_code"));}need(jdbc.update("UPDATE "+table+" SET "+p+"_actual_number="+p+"_actual_number+?,"+p+"_available_number="+p+"_available_number+?,"+p+"_lock_number="+p+"_lock_number+?,version=version+1 WHERE company_code=? AND "+where,args.toArray())==1,"库存归属已变化");}}
 private void summary(String c,String sku,long total,long available,long allocated,long frozen){Map<String,Object> o=one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=?",c,sku);need(n(o,"total_stock")+total>=0&&n(o,"available_stock")+available>=0&&n(o,"allocated_stock")+allocated>=0&&n(o,"frozen_stock")+frozen>=0,"商品汇总库存不足，请核对正次品口径");jdbc.update("UPDATE oms_inventory SET total_stock=total_stock+?,available_stock=available_stock+?,allocated_stock=allocated_stock+?,frozen_stock=frozen_stock+?,version=version+1 WHERE company_code=? AND sku_sn=?",total,available,allocated,frozen,c,sku);}
 private void journal(String c,String sn,String event,String op,Map<String,Object> before,String type,long q,String actor){Map<String,Object> after=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",c,before.get("id"));List<Object> a=new ArrayList<>(Arrays.asList(c,before.get("store_code"),before.get("sku_sn"),before.get("id"),before.get("batch_code"),type,op,hash(sn+"/"+op+"/"+type+"/"+event),sn,q,"采购退供或质量处理",0,actor));StringBuilder cols=new StringBuilder("company_code,store_code,sku_sn,batch_id,batch_code,inventory_type,operation_type,request_id,relation_sn,change_quantity,change_reason,operator_id,operator_name");for(String key:InventoryQueryService.QUANTITIES){cols.append(",old_").append(key).append(",new_").append(key);a.add(before.get(key));a.add(after.get(key));}jdbc.update("INSERT INTO wms_inventory_change_history("+cols+") VALUES ("+String.join(",",Collections.nCopies(a.size(),"?"))+")",a.toArray());jdbc.update("INSERT INTO oms_allocation_stock_signal(company_code,sku_sn,store_code) VALUES (?,?,?) ON DUPLICATE KEY UPDATE revision=revision+1,update_time=NOW()",c,before.get("sku_sn"),before.get("store_code"));}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED,timeout=20)
 public Map<String,Object> execute(String c,String action,Map<String,Object> cmd){String sn=s(cmd,"document_sn");identity(c,sn);need(Arrays.asList("reserve","post","release","recover","rehold").contains(action),"库存处理动作无效");List<Map<String,Object>> lines="reserve".equals(action)?rows(cmd.get("lines")):jdbc.queryForList("SELECT * FROM oms_stock_care_line WHERE company_code=? AND document_sn=? ORDER BY sku_sn,store_code,batch_id,line_key",c,sn);need(!lines.isEmpty()&&lines.size()<=200,"库存处理明细须为1至200行");lockSkus(c,lines);
  if("reserve".equals(action))reserve(c,sn,cmd,lines);else{Map<String,Object> d=one("SELECT * FROM oms_stock_care WHERE company_code=? AND document_sn=? FOR UPDATE",c,sn);lines=jdbc.queryForList("SELECT * FROM oms_stock_care_line WHERE company_code=? AND document_sn=? ORDER BY sku_sn,store_code,batch_id,line_key",c,sn);if("rehold".equals(action))rehold(c,sn,cmd,d,lines);else if("post".equals(action))post(c,sn,cmd,d,lines);else if("recover".equals(action))recover(c,sn,cmd,d,lines);else release(c,sn,cmd,d,lines);}return report(c,sn);
 }
 private void reserve(String c,String sn,Map<String,Object> cmd,List<Map<String,Object>> lines){String purpose=s(cmd,"purpose"),digest=hash(cmd);need(Arrays.asList("RETURN","QUALITY").contains(purpose),"库存锁定用途无效");List<Map<String,Object>> prior=jdbc.queryForList("SELECT * FROM oms_stock_care WHERE company_code=? AND document_sn=? FOR UPDATE",c,sn);if(!prior.isEmpty()){need(digest.equals(prior.get(0).get("payload_hash")),"同一来源的锁定内容发生变化");return;}jdbc.update("INSERT INTO oms_stock_care(company_code,document_sn,purpose,payload_hash) VALUES (?,?,?,?)",c,sn,purpose,digest);Set<Long> seen=new HashSet<>();List<Map<String,Object>> sorted=new ArrayList<>(lines);sorted.sort(Comparator.comparing(l->s(l,"sku_sn")+"/"+s(l,"store_code")+"/"+s(l,"batch_code")));
  for(Map<String,Object> l:sorted){long q=n(l,"quantity"),key=n(l,"line_key");String type=s(l,"inventory_type"),sku=s(l,"sku_sn"),store=s(l,"store_code");need(q>0&&q<=100000000&&key>0&&seen.add(key)&&Arrays.asList("ZP","CP").contains(type),"锁定行或数量重复无效");consistent(c,sku,store);Map<String,Object> b=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=? AND batch_code=? FOR UPDATE",c,sku,store,l.get("batch_code"));if("RETURN".equals(purpose)){need(jdbc.queryForObject("SELECT COUNT(*) FROM wms_inventory_change_history WHERE company_code=? AND sku_sn=? AND batch_id=? AND operation_type='RECEIVE' AND relation_sn=?",Long.class,c,sku,b.get("id"),l.get("origin_relation"))>0,"缺少对应原入库成功流水");}
   if("ZP".equals(type))need(mutations.allocationAvailable(c,sku,Collections.singletonList(store))>=q,"不能占用订单预占、福袋保障或其他已锁定的正品库存");change(c,b,type,0,-q,q);boolean good="ZP".equals(type);summary(c,sku,0,good?-q:0,"RETURN".equals(purpose)?q:0,"RETURN".equals(purpose)?(good?0:-q):(good?q:0));jdbc.update("INSERT INTO oms_stock_care_line(company_code,document_sn,line_key,batch_id,sku_sn,store_code,inventory_type,quantity,planned_quantity) VALUES (?,?,?,?,?,?,?,?,?)",c,sn,key,b.get("id"),sku,store,type,q,q);journal(c,sn,"HOLD-"+key,purpose.equals("RETURN")?"RETURN_HOLD":"QUALITY_FREEZE",b,type,q,s(cmd,"actor"));
  }
 }
 private void post(String c,String sn,Map<String,Object> cmd,Map<String,Object> d,List<Map<String,Object>> holds){need("RETURN".equals(d.get("purpose")),"质量冻结不能当作退供出库扣账");String msg=s(cmd,"message_id"),digest=hash(cmd);need(!msg.isEmpty()&&msg.length()<=128,"出库事件身份缺失");List<Map<String,Object>> old=jdbc.queryForList("SELECT payload_hash FROM oms_stock_care_event WHERE company_code=? AND document_sn=? AND message_id=?",c,sn,msg);if(!old.isEmpty()){need(digest.equals(old.get(0).get("payload_hash")),"相同出库事件内容变化");return;}need("HELD".equals(d.get("state")),"原退供占用已经结束，迟到回传须先核对");Map<Long,Map<String,Object>> index=new HashMap<>();holds.forEach(l->index.put(n(l,"line_key"),l));Set<Long> seen=new HashSet<>();for(Map<String,Object> l:rows(cmd.get("lines"))){long key=n(l,"line_key"),q=n(l,"quantity");Map<String,Object> h=index.get(key);need(h!=null&&seen.add(key)&&q>0&&q<=n(h,"quantity")-n(h,"consumed_quantity")-n(h,"released_quantity"),"出库超过本来源尚未消耗的锁定数量");Map<String,Object> b=batch(c,n(h,"batch_id"));consistent(c,s(h,"sku_sn"),s(h,"store_code"));change(c,b,s(h,"inventory_type"),-q,0,-q);summary(c,s(h,"sku_sn"),-q,0,-q,0);jdbc.update("UPDATE oms_stock_care_line SET consumed_quantity=consumed_quantity+? WHERE company_code=? AND document_sn=? AND line_key=?",q,c,sn,key);journal(c,sn,msg+"/"+key,"RETURN_OUT",b,s(h,"inventory_type"),-q,s(cmd,"actor"));}jdbc.update("INSERT INTO oms_stock_care_event(company_code,document_sn,message_id,payload_hash) VALUES (?,?,?,?)",c,sn,msg,digest);if(jdbc.queryForObject("SELECT COALESCE(SUM(quantity-consumed_quantity-released_quantity),0) FROM oms_stock_care_line WHERE company_code=? AND document_sn=?",Long.class,c,sn)==0)jdbc.update("UPDATE oms_stock_care SET state='COMPLETED' WHERE company_code=? AND document_sn=?",c,sn);
 }
 private void release(String c,String sn,Map<String,Object> cmd,Map<String,Object> d,List<Map<String,Object>> holds){boolean quality="QUALITY".equals(d.get("purpose"));String msg=quality?s(cmd,"message_id"):s(cmd,"message_id").isEmpty()?"RELEASE":s(cmd,"message_id");need(!msg.isEmpty(),"释放请求身份缺失");String digest=hash(cmd);List<Map<String,Object>> old=jdbc.queryForList("SELECT payload_hash FROM oms_stock_care_event WHERE company_code=? AND document_sn=? AND message_id=?",c,sn,msg);if(!old.isEmpty()){need(digest.equals(old.get(0).get("payload_hash")),"同一释放请求内容变化");return;}need("HELD".equals(d.get("state")),"原来源已结束，不能重复释放");for(Map<String,Object> h:holds){long remaining=n(h,"quantity")-n(h,"consumed_quantity")-n(h,"released_quantity"),q=quality?n(cmd,"quantity"):remaining;if(!quality&&q==0)continue;need(q>0&&q<=remaining,"解冻数量超过原冻结余额");if(q==0)continue;Map<String,Object> b=batch(c,n(h,"batch_id"));consistent(c,s(h,"sku_sn"),s(h,"store_code"));String type=s(h,"inventory_type");change(c,b,type,0,q,-q);boolean good=type.equals("ZP");summary(c,s(h,"sku_sn"),0,good?q:0,quality?0:-q,quality?(good?-q:0):(good?0:q));jdbc.update("UPDATE oms_stock_care_line SET released_quantity=released_quantity+? WHERE company_code=? AND document_sn=? AND line_key=?",q,c,sn,h.get("line_key"));journal(c,sn,msg+"/"+h.get("line_key"),quality?"QUALITY_RELEASE":"RETURN_RELEASE",b,type,q,s(cmd,"actor"));}jdbc.update("INSERT INTO oms_stock_care_event(company_code,document_sn,message_id,payload_hash) VALUES (?,?,?,?)",c,sn,msg,digest);if(jdbc.queryForObject("SELECT SUM(quantity-consumed_quantity-released_quantity) FROM oms_stock_care_line WHERE company_code=? AND document_sn=?",Long.class,c,sn)==0)jdbc.update("UPDATE oms_stock_care SET state='RELEASED' WHERE company_code=? AND document_sn=?",c,sn);for(Map<String,Object> h:holds)OrderStockService.replanPending(jdbc,c,s(h,"sku_sn"));}
 private void rehold(String c,String sn,Map<String,Object>cmd,Map<String,Object>d,List<Map<String,Object>>holds){
  need("RETURN".equals(d.get("purpose")),"仅退仓业务允许恢复占用");String message="REHOLD_"+hash(s(cmd,"message_id")),digest=hash(cmd);need(!s(cmd,"message_id").isEmpty(),"恢复占用需要独立请求身份");List<String>prior=jdbc.queryForList("SELECT payload_hash FROM oms_stock_care_event WHERE company_code=? AND document_sn=? AND message_id=?",String.class,c,sn,message);if(!prior.isEmpty()){need(digest.equals(prior.get(0)),"相同恢复请求内容变化");return;}
  Map<Long,Map<String,Object>>index=new HashMap<>();for(Map<String,Object>h:holds)index.put(n(h,"line_key"),h);Set<Long>seen=new HashSet<>();List<Map<String,Object>>rows=rows(cmd.get("lines"));need(!rows.isEmpty()&&rows.size()<=200,"恢复占用明细无效");for(Map<String,Object>l:rows){long key=n(l,"line_key"),q=n(l,"quantity");Map<String,Object>h=index.get(key);need(h!=null&&seen.add(key)&&q>0&&n(h,"planned_quantity")>0&&q<=n(h,"planned_quantity")-n(h,"quantity")+n(h,"released_quantity"),"恢复占用超过原计划尚未执行余量");String sku=s(h,"sku_sn"),store=s(h,"store_code"),type=s(h,"inventory_type");consistent(c,sku,store);Map<String,Object>b=batch(c,n(h,"batch_id"));if(type.equals("ZP"))need(mutations.allocationAvailable(c,sku,Collections.singletonList(store))>=q,"原批次可用不足或已被订单预占，不能恢复退仓占用");change(c,b,type,0,-q,q);summary(c,sku,0,type.equals("ZP")?-q:0,q,type.equals("CP")?-q:0);jdbc.update("UPDATE oms_stock_care_line SET quantity=quantity+? WHERE company_code=? AND document_sn=? AND line_key=?",q,c,sn,key);journal(c,sn,message+"/"+key,"RETURN_REHOLD",b,type,q,s(cmd,"actor"));}jdbc.update("UPDATE oms_stock_care SET state='HELD' WHERE company_code=? AND document_sn=?",c,sn);jdbc.update("INSERT INTO oms_stock_care_event(company_code,document_sn,message_id,payload_hash) VALUES (?,?,?,?)",c,sn,message,digest);
 }
 private void recover(String c,String sn,Map<String,Object> cmd,Map<String,Object> d,List<Map<String,Object>> holds){
  need("RETURN".equals(d.get("purpose")),"仅实际退仓出库允许独立收回入库");String msg="RECOVER_"+hash(s(cmd,"message_id")),digest=hash(cmd);need(!s(cmd,"message_id").isEmpty(),"收回事件身份缺失");
  List<Map<String,Object>> old=jdbc.queryForList("SELECT payload_hash FROM oms_stock_care_event WHERE company_code=? AND document_sn=? AND message_id=?",c,sn,msg);if(!old.isEmpty()){need(digest.equals(old.get(0).get("payload_hash")),"同一收回事件内容变化");return;}
  Map<Long,Map<String,Object>> index=new HashMap<>();for(Map<String,Object> h:holds)index.put(n(h,"line_key"),h);Set<String> seen=new HashSet<>();List<Map<String,Object>> receipts=rows(cmd.get("lines"));need(!receipts.isEmpty()&&receipts.size()<=400,"收回明细须为1至400行");
  for(Map<String,Object> l:receipts){long key=n(l,"line_key"),q=n(l,"quantity");String type=s(l,"inventory_type"),origin=s(l,"origin_relation");Map<String,Object> h=index.get(key);need(h!=null&&q>0&&Arrays.asList("ZP","CP").contains(type)&&origin.matches("PURCHASE_RECLAIM_[0-9]+")&&seen.add(origin),"收回商品原行、数量或实收来源无效");
   need(jdbc.update("UPDATE oms_stock_care_line SET recovered_quantity=recovered_quantity+? WHERE company_code=? AND document_sn=? AND line_key=? AND consumed_quantity-recovered_quantity>=?",q,c,sn,key,q)==1,"收回数量超过原实际出库尚未收回数量");
   Map<String,Object> b=batch(c,n(h,"batch_id"));consistent(c,s(h,"sku_sn"),s(h,"store_code"));change(c,b,type,q,q,0);summary(c,s(h,"sku_sn"),q,type.equals("ZP")?q:0,0,type.equals("CP")?q:0);journal(c,origin,msg+"/"+key,"RECEIVE",b,type,q,s(cmd,"actor"));OrderStockService.replanPending(jdbc,c,s(h,"sku_sn"));
  }
  jdbc.update("INSERT INTO oms_stock_care_event(company_code,document_sn,message_id,payload_hash) VALUES (?,?,?,?)",c,sn,msg,digest);
 }
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED,timeout=20)
 public void convert(String c,String sn,long batchId,long quantity,String actor){identity(c,sn);Map<String,Object> hint=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",c,batchId);lockSkus(c,Collections.singletonList(hint));consistent(c,s(hint,"sku_sn"),s(hint,"store_code"));Map<String,Object> b=batch(c,batchId);need(quantity>0,"转正数量须大于0");change(c,b,"CP",-quantity,-quantity,0);journal(c,sn,"CP","QUALITY_BAD_OUT",b,"CP",-quantity,actor);b=batch(c,batchId);change(c,b,"ZP",quantity,quantity,0);summary(c,s(b,"sku_sn"),0,quantity,0,-quantity);journal(c,sn,"ZP","QUALITY_GOOD_IN",b,"ZP",quantity,actor);OrderStockService.replanPending(jdbc,c,s(b,"sku_sn"));}
}
